import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.reduce.js";
import axios from '../axios';
import * as bootstrap from 'bootstrap';
export default {
  data() {
    return {
      products: [],
      filteredProducts: [],
      // New property for filtered products
      searchQuery: '',
      // New property for search query
      users: [],
      orders: [],
      // Added orders array to store order data
      newProduct: {
        name: '',
        description: '',
        price: 0,
        stock: 0
      },
      editProduct: {
        id: null,
        name: '',
        description: '',
        price: 0,
        stock: 0
      },
      selectedImage: null,
      selectedEditImage: null,
      modalInstance: null,
      deleteModalInstance: null,
      productToDelete: null,
      currentView: 'grid' // Add this line - default view is grid
    };
  },
  computed: {
    // Total number of orders
    totalOrders() {
      return this.orders.length;
    },
    // Calculate total inventory value (price * stock for all products)
    totalInventoryValue() {
      if (!this.products || this.products.length === 0) return 0;
      return this.products.reduce((total, product) => {
        const productValue = (product.price || 0) * (product.stock || 0);
        return total + productValue;
      }, 0);
    }
  },
  methods: {
    // Search functionality
    filterProducts() {
      if (!this.searchQuery.trim()) {
        this.filteredProducts = [...this.products];
        return;
      }
      const query = this.searchQuery.toLowerCase().trim();
      this.filteredProducts = this.products.filter(product => {
        // Search in name
        if (product.name.toLowerCase().includes(query)) {
          return true;
        }

        // Search in description
        if (product.description.toLowerCase().includes(query)) {
          return true;
        }

        // Search in price (convert to string first)
        if (product.price.toString().includes(query)) {
          return true;
        }
        return false;
      });
    },
    clearSearch() {
      this.searchQuery = '';
      this.filteredProducts = [...this.products];
    },
    fullImageUrl(path) {
      if (path.startsWith('http')) return path;
      return `http://127.0.0.1:8000${path.startsWith('/') ? path : '/media/' + path}`;
    },
    handleImage(e) {
      this.selectedImage = e.target.files[0];
    },
    async fetchProducts() {
      try {
        const res = await axios.get('products/');
        this.products = res.data;
        this.filteredProducts = [...this.products]; // Initialize filtered products with all products
      } catch (err) {
        this.showToast('Failed to fetch products', 'danger');
      }
    },
    // New method to fetch orders
    async fetchOrders() {
      try {
        const res = await axios.get('admin-orders/');
        this.orders = res.data;
      } catch (err) {
        console.error('Failed to fetch orders:', err);
        // Don't show error toast for orders as it may not be critical
        // and the API endpoint might not be ready yet
        this.orders = []; // Set to empty array to avoid undefined errors
      }
    },
    async addProduct() {
      const formData = new FormData();
      for (let key in this.newProduct) {
        formData.append(key, this.newProduct[key]);
      }
      if (this.selectedImage) {
        formData.append('image', this.selectedImage);
      }
      try {
        await axios.post('products/', formData, {
          headers: {
            'Content-Type': 'multipart/form-data'
          }
        });
        this.showToast('Product added successfully!', 'success');
        this.newProduct = {
          name: '',
          description: '',
          price: 0,
          stock: 0
        };
        this.selectedImage = null;
        this.fetchProducts();
        // Close the form
        const collapseElement = document.getElementById('addProductForm');
        const bsCollapse = bootstrap.Collapse.getInstance(collapseElement);
        if (bsCollapse) bsCollapse.hide();
      } catch (err) {
        this.showToast('Failed to add product', 'danger');
      }
    },
    confirmDelete(product) {
      this.productToDelete = product;
      this.deleteModalInstance = new bootstrap.Modal(document.getElementById('deleteModal'));
      this.deleteModalInstance.show();
    },
    closeDeleteModal() {
      if (this.deleteModalInstance) this.deleteModalInstance.hide();
      this.productToDelete = null;
    },
    async deleteProduct(id) {
      if (!id) return;
      try {
        await axios.delete(`products/${id}/`);
        this.showToast('Product deleted successfully', 'success');
        this.fetchProducts();
        this.closeDeleteModal();
      } catch (err) {
        this.showToast('Cannot delete. Product may be in an order.', 'danger');
        this.closeDeleteModal();
      }
    },
    openEditModal(product) {
      this.editProduct = {
        ...product
      };
      this.selectedEditImage = null;
      this.modalInstance = new bootstrap.Modal(document.getElementById('editModal'));
      this.modalInstance.show();
    },
    closeEditModal() {
      if (this.modalInstance) this.modalInstance.hide();
    },
    async submitEdit() {
      try {
        const formData = new FormData();
        for (let key in this.editProduct) {
          if (key !== 'image') {
            formData.append(key, this.editProduct[key]);
          }
        }
        if (this.selectedEditImage) {
          formData.append('image', this.selectedEditImage);
        }
        await axios.patch(`products/${this.editProduct.id}/`, formData, {
          headers: {
            'Content-Type': 'multipart/form-data'
          }
        });
        this.showToast('Product updated successfully!', 'success');
        this.fetchProducts();
        this.closeEditModal();
      } catch (err) {
        console.error(err);
        this.showToast('Failed to update product', 'danger');
      }
    },
    showToast(message, type = 'primary') {
      // Create toast container if it doesn't exist
      let toastContainer = document.getElementById('toast-container');
      if (!toastContainer) {
        toastContainer = document.createElement('div');
        toastContainer.id = 'toast-container';
        toastContainer.className = 'toast-container position-fixed bottom-0 end-0 p-3';
        document.body.appendChild(toastContainer);
      }

      // Create toast element
      const toastEl = document.createElement('div');
      toastEl.className = `toast align-items-center text-white bg-${type} border-0`;
      toastEl.setAttribute('role', 'alert');
      toastEl.setAttribute('aria-live', 'assertive');
      toastEl.setAttribute('aria-atomic', 'true');
      toastEl.innerHTML = `
          <div class="d-flex">
            <div class="toast-body">
              ${message}
            </div>
            <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button>
          </div>
        `;
      toastContainer.appendChild(toastEl);
      const toast = new bootstrap.Toast(toastEl, {
        autohide: true,
        delay: 3000
      });
      toast.show();

      // Remove toast element after it's hidden
      toastEl.addEventListener('hidden.bs.toast', () => {
        toastEl.remove();
      });
    }
  },
  mounted() {
    const token = localStorage.getItem('access');
    const isStaff = localStorage.getItem('is_staff') === 'true';
    if (!token || !isStaff) {
      this.showToast('Access denied. Staff only.', 'danger');
      this.$router.push('/login');
      return;
    }
    this.fetchProducts();
    this.fetchOrders(); // Fetch orders when component mounts

    // Check for saved view preference in localStorage
    const savedView = localStorage.getItem('productView');
    if (savedView) {
      this.currentView = savedView;
    }
  },
  watch: {
    // Save view preference when it changes
    currentView(newView) {
      localStorage.setItem('productView', newView);
    },
    // Auto-filter products when search query changes
    searchQuery() {
      this.filterProducts();
    },
    // Update filtered products when main products list changes
    products: {
      handler(newProducts) {
        console.log(newProducts);
        this.filterProducts();
      },
      deep: true
    }
  }
};
